                  <button onClick={vm.vb?.importBulk} style={{border: "1px solid #e1e3dc", background: "#fff", color: "#3a3b3d", padding: "10px 16px", borderRadius: "12px", fontSize: "13px", fontWeight: "700", cursor: "pointer", fontFamily: "inherit"}}>{"افزودن همه"}</button>
